"""Legacy startup DDL retained only to reproduce the cross-connection lock defect."""
def ensure_agent_security_tables(cursor) -> None:
    cursor.execute("\n        CREATE TABLE IF NOT EXISTS agent_clients (\n            id TEXT PRIMARY KEY,\n            owner_user_id TEXT NOT NULL,\n            organization_name TEXT NOT NULL,\n            contact_email TEXT NOT NULL,\n            key_hash TEXT NOT NULL,\n            status TEXT NOT NULL DEFAULT 'sandbox',\n            allowed_scopes JSONB NOT NULL DEFAULT '[]'::jsonb,\n            rate_limits JSONB NOT NULL DEFAULT '{}'::jsonb,\n            metadata_json JSONB NOT NULL DEFAULT '{}'::jsonb,\n            created_at TIMESTAMPTZ DEFAULT NOW(),\n            updated_at TIMESTAMPTZ DEFAULT NOW(),\n            last_seen_at TIMESTAMPTZ\n        )\n        ")
    cursor.execute("\n        CREATE TABLE IF NOT EXISTS agent_action_ledger (\n            id TEXT PRIMARY KEY,\n            agent_client_id TEXT,\n            business_id TEXT,\n            action_type TEXT NOT NULL,\n            capability TEXT,\n            required_scope TEXT,\n            risk_level TEXT NOT NULL,\n            input_summary TEXT,\n            output_summary TEXT,\n            approval_id TEXT,\n            status TEXT NOT NULL,\n            reason_code TEXT,\n            ip TEXT,\n            user_agent TEXT,\n            metadata_json JSONB NOT NULL DEFAULT '{}'::jsonb,\n            created_at TIMESTAMPTZ DEFAULT NOW()\n        )\n        ")
    cursor.execute("\n        CREATE TABLE IF NOT EXISTS agent_discovery_events (\n            id TEXT PRIMARY KEY,\n            event_type TEXT NOT NULL,\n            path TEXT NOT NULL,\n            method TEXT NOT NULL,\n            status_code INT,\n            agent_family TEXT NOT NULL DEFAULT 'unknown',\n            ip_hash TEXT,\n            user_agent TEXT,\n            referrer TEXT,\n            metadata_json JSONB NOT NULL DEFAULT '{}'::jsonb,\n            created_at TIMESTAMPTZ DEFAULT NOW()\n        )\n        ")
    cursor.execute('CREATE UNIQUE INDEX IF NOT EXISTS uq_agent_clients_key_hash ON agent_clients(key_hash)')
    cursor.execute('CREATE INDEX IF NOT EXISTS idx_agent_clients_owner ON agent_clients(owner_user_id, created_at DESC)')
    cursor.execute('CREATE INDEX IF NOT EXISTS idx_agent_clients_status ON agent_clients(status)')
    cursor.execute('CREATE INDEX IF NOT EXISTS idx_agent_action_ledger_client_created ON agent_action_ledger(agent_client_id, created_at DESC)')
    cursor.execute('CREATE INDEX IF NOT EXISTS idx_agent_action_ledger_business_created ON agent_action_ledger(business_id, created_at DESC)')
    cursor.execute('CREATE INDEX IF NOT EXISTS idx_agent_action_ledger_risk ON agent_action_ledger(risk_level, created_at DESC)')
    cursor.execute('CREATE INDEX IF NOT EXISTS idx_agent_action_ledger_status ON agent_action_ledger(status, created_at DESC)')
    cursor.execute('CREATE INDEX IF NOT EXISTS idx_agent_discovery_events_created ON agent_discovery_events(created_at DESC)')
    cursor.execute('CREATE INDEX IF NOT EXISTS idx_agent_discovery_events_family_created ON agent_discovery_events(agent_family, created_at DESC)')
    cursor.execute('CREATE INDEX IF NOT EXISTS idx_agent_discovery_events_type_created ON agent_discovery_events(event_type, created_at DESC)')
